#include "catalog/ring_exchange.h"
#include <algorithm>
#include <cmath>
namespace catalog {
void RingExchange::validate() const {require(lx>=2&&ly>=2&&cells()<=12,"Ring reference geometry 2<=lx,ly and <=12 cells");require(std::isfinite(hopping)&&std::isfinite(ring)&&std::isfinite(repulsion)&&std::isfinite(chemical),"Ring parameters must be real finite");}
std::vector<std::pair<int,int>> RingExchange::edges() const {validate();std::vector<std::pair<int,int>> e;for(int x=0;x<lx;++x)for(int y=0;y<ly;++y){int r=x*ly+y;if(x+1<lx)e.emplace_back(r,r+ly);if(y+1<ly)e.emplace_back(r,r+1);}return e;}
std::vector<std::array<int,4>> RingExchange::squares() const {validate();std::vector<std::array<int,4>> out;for(int x=0;x+1<lx;++x)for(int y=0;y+1<ly;++y){int r=x*ly+y;out.push_back({r,r+1,r+ly+1,r+ly});}return out;}
std::vector<PairMove> RingExchange::moves() const {std::vector<PairMove> out;for(auto [i,j]:edges())out.push_back({{i,j},hopping});for(auto p:squares())out.push_back({{p[0],p[1],p[2],p[3]},ring});return out;}
double RingExchange::diagonalEnergy(std::uint64_t s) const {double e=0.;for(int r=0;r<cells();++r)e-=chemical*__builtin_popcountll((s>>(2*r))&3);for(auto [i,j]:edges())e+=repulsion*(__builtin_popcountll((s>>(2*i))&3)-1)*(__builtin_popcountll((s>>(2*j))&3)-1);return e;}
std::vector<std::uint64_t> RingExchange::nextStates(std::uint64_t s) const {require(s<(std::uint64_t(1)<<modes()),"Ring occupation outside Fock space");std::vector<std::uint64_t> out;for(auto move:moves()) {bool good=true;int first=(s>>(2*move.cells[0]))&3;std::uint64_t mask=0;for(int k=0;k<int(move.cells.size());++k){int p=(s>>(2*move.cells[k]))&3;good&=(p==0||p==3)&&p==(k%2?3-first:first);mask|=std::uint64_t(3)<<(2*move.cells[k]);}if(good)out.push_back(s^mask);}return out;}
bool RingExchange::valid(const LinkPath& p) const {validate();if(!std::isfinite(p.beta)||p.beta<=0||p.states.empty()||p.times.size()+1!=p.states.size()||p.states.front()!=p.states.back())return false;double last=0.;for(auto s:p.states)if(s>=(std::uint64_t(1)<<modes()))return false;for(int k=0;k<int(p.times.size());++k){if(!std::isfinite(p.times[k])||p.times[k]<last||p.times[k]>p.beta)return false;last=p.times[k];auto next=nextStates(p.states[k]);if(std::find(next.begin(),next.end(),p.states[k+1])==next.end())return false;}return true;}
double RingExchange::moveCoupling(std::uint64_t a,std::uint64_t b) const {auto next=nextStates(a);require(std::find(next.begin(),next.end(),b)!=next.end(),"Invalid ring transition");auto diff=a^b;for(auto m:moves()){std::uint64_t mask=0;for(int r:m.cells)mask|=std::uint64_t(3)<<(2*r);if(mask==diff)return m.coupling;}throw std::runtime_error("Ring transition not found");}
MatType RingExchange::rotation(std::uint64_t a,std::uint64_t b) const {(void)moveCoupling(a,b);MatType A=MatType::Zero(2*modes(),2*modes());for(int r=0;r<cells();++r)if(((a^b)>>(2*r))&3){auto pair=pairMajorana(modes(),2*r,2*r+1,1.,false);A+=(((a>>(2*r))&3)?-.5:.5)*std::acos(-1.)*(pair-pair.adjoint());}return A;}
DataType RingExchange::weight(const LinkPath& p) const {if(!valid(p))return 0.;std::vector<Gaussian> fs;double scalar=1.,last=0.;for(int k=0;k<int(p.times.size());++k){scalar*=moveCoupling(p.states[k],p.states[k+1])*std::exp(-(p.times[k]-last)*diagonalEnergy(p.states[k]));last=p.times[k];fs.push_back(linkOccupationProjector(modes(),p.states[k]));fs.push_back(gaussian(rotation(p.states[k],p.states[k+1])));}fs.push_back(linkOccupationProjector(modes(),p.states.back()));return scalar*std::exp(-(p.beta-last)*diagonalEnergy(p.states.back()))*traceGaussianFactors(fs);}
DataType RingExchange::reference(const LinkPath& p) const {if(!valid(p))return 0.;double z=1.,last=0.;for(int k=0;k<int(p.times.size());++k){z*=moveCoupling(p.states[k],p.states[k+1])*std::exp(-(p.times[k]-last)*diagonalEnergy(p.states[k]));last=p.times[k];}return z*std::exp(-(p.beta-last)*diagonalEnergy(p.states.back()));}
MatType RingExchange::exactHamiltonian() const {
 validate();int n=modes();require(n<=8,"Ring independent Fock oracle limited to eight modes");int dim=1<<n;MatType h=MatType::Zero(dim,dim);
 // Apply written fermion monomials right-to-left, keeping every CAR sign.
 auto add=[&](const std::vector<std::pair<int,bool>>& operators,double coefficient){for(unsigned s=0;s<unsigned(dim);++s){unsigned t=s;int sign=1;bool good=true;for(auto it=operators.rbegin();it!=operators.rend();++it){int i=it->first;bool occupied=(t>>i)&1;if(occupied==it->second){good=false;break;}if(__builtin_popcount(t&((1u<<i)-1))%2)sign=-sign;t^=1u<<i;}if(good)h(t,s)+=coefficient*sign;}};
 for(auto move:moves())for(int reverse=0;reverse<2;++reverse){std::vector<std::pair<int,bool>> ops;for(int k=0;k<int(move.cells.size());++k){int a=2*move.cells[k];bool create=(k%2)==reverse;if(create){ops.emplace_back(a,true);ops.emplace_back(a+1,true);}else{ops.emplace_back(a+1,false);ops.emplace_back(a,false);}}add(ops,-move.coupling);}
 for(unsigned s=0;s<unsigned(dim);++s){double e=0.;for(int r=0;r<cells();++r)e-=chemical*(int((s>>(2*r))&1)+int((s>>(2*r+1))&1));for(auto [i,j]:edges()){int a=int((s>>(2*i))&1)+int((s>>(2*i+1))&1),b=int((s>>(2*j))&1)+int((s>>(2*j+1))&1);e+=repulsion*(a-1)*(b-1);}h(s,s)+=e;}return h;
}
}
